    /**
     * Tests getting all Agencys.
     *
     * @return    Collection
     */
    public List<Agency> testGetAll() throws Throwable {
    LOGGER.info( "AgencyTest:testGetAll() - Retrieving Collection of Agencys:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all Agency : " );
    List<Agency> collection  = null;

    try {
        // call the static get method on the AgencyService
        collection = service.getAllAgency();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            Agency currEntity  = null;
            Iterator<Agency> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getAgencyId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

